pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newLog) public {
        vm.assume(actor != address(0));
        vm.assume(newLog != address(0));

        vm.prank(actor);
        c.SetLogFile(newLog);
        address before = c.Log();

        vm.prank(actor);
        c.Initialized();

        vm.prank(actor);
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }

        // Rule: after initialization, SetLogFile always reverts and the Log
        // address is locked. The mutant allows it to succeed and change.
        assertTrue(!ok && c.Log() == before);
    }
}

