pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint96 amount, address newLog) public {
        vm.assume(actor != address(0) && actor != address(c));
        LogFile log1 = new LogFile();
        c.SetMinSum(0);
        c.SetLogFile(address(log1));
        c.Initialized();

        // After initialization, SetLogFile must be locked out.
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }

        // Deposits must still be logged in the pre-initialization log.
        vm.deal(actor, uint256(amount));
        vm.prank(actor);
        c.Deposit{value: uint256(amount)}();

        (, , uint lastVal) = log1.History(0);
        assertTrue(!ok && log1.History().length == 1 && lastVal == uint256(amount));
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

