pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetLogFile(address(new LogHelper()));
        c.Initialized();
    }
    function testFuzz_property(address actor, address newLog, uint256 amount) public {
        vm.assume(actor != address(0));
        // After initialization, attempts to change the log must not take effect,
        // so subsequent deposits must still succeed for ANY actor and amount.
        try c.SetLogFile(newLog) { /* mutant accepts; reference reverts */ } catch { /* reference */ }
        vm.deal(actor, amount);
        vm.prank(actor);
        bool depositOk;
        if (amount == 0) {
            c.Deposit();
            depositOk = true;
        } else {
            try c.Deposit{value: amount}() { depositOk = true; } catch { depositOk = false; }
        }
        assertTrue(depositOk);
    }
}

contract LogHelper {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

